  "approach_families": [
    {
      "family": "state machine with front‑gap stop/detour",
      "turns": "1,3,8,10,11,12,13,15,17",
      "result": "59 passes / 76 runs (≈78%); collisions still frequent."
    },
    {
      "family": "candidate scoring & evasion (evade/_safe_evade)",
      "turns": "2,5,6,7,14,16",
